<script setup lang="ts">
const route=useRoute(),{api,token}=useShopApi(),isProduct=computed(()=>/^\/products\/[^/]+$/.test(route.path));const product=ref<any>(),related=ref<any[]>([]),questions=ref<any>(),history=ref<any[]>([]),question=ref(''),message=ref(''),alerted=ref(false);const points=computed(()=>{if(history.value.length<2)return'';const prices=history.value.map(i=>Number(i.price)),min=Math.min(...prices),range=Math.max(Math.max(...prices)-min,1);return prices.map((p,i)=>`${i/(prices.length-1)*100},${45-(p-min)/range*40}`).join(' ')});async function load(){if(!isProduct.value)return;product.value=await api<any>(`/catalog/products/${route.params.slug}`);[related.value,questions.value,history.value]=await Promise.all([api<any[]>(`/catalog/products/${product.value.id}/related`),api<any>(`/catalog/products/${product.value.id}/questions`),api<any[]>(`/catalog/products/${product.value.id}/price-history`)])}watch(()=>route.fullPath,load,{immediate:true});async function ask(){if(!token.value)return navigateTo(`/login?redirect=${encodeURIComponent(route.fullPath)}`);const r=await api<any>(`/catalog/products/${product.value.id}/questions`,{method:'POST',body:{question:question.value}});message.value=r.message;question.value=''}async function toggleAlert(){if(!token.value)return navigateTo('/login');const v=product.value.variants?.[0],r=await api<any>(`/catalog/products/${product.value.id}/alerts`,{method:'POST',body:{type:v?.stock?'price_drop':'back_in_stock',variant_id:v?.id,target_price:v?.stock?Math.floor(v.price*.9):null}});alerted.value=r.enabled}
</script>
<template><div v-if="isProduct&&product" class="mx-auto max-w-7xl space-y-6 px-4 pt-6"><section class="grid gap-6 md:grid-cols-2"><div class="rounded-3xl border bg-white p-6 md:p-8"><h2 class="text-xl font-black">اطلاع‌رسانی هوشمند</h2><p class="mt-2 text-sm leading-7 text-slate-500">اگر قیمت کاهش یافت یا محصول موجود شد، از طریق پیامک به شما خبر می‌دهیم.</p><button :class="['mt-5 rounded-xl px-5 py-3 text-sm font-bold',alerted?'bg-emerald-50 text-emerald-700':'bg-brand-700 text-white']" @click="toggleAlert">{{alerted?'اعلان فعال شد ✓':'فعال‌کردن اعلان'}}</button></div><div class="rounded-3xl border bg-white p-6 md:p-8"><div class="flex items-center justify-between"><h2 class="text-xl font-black">روند تغییر قیمت</h2><span class="text-xs text-slate-400">{{history.length}} تغییر</span></div><svg v-if="points" viewBox="0 0 100 50" preserveAspectRatio="none" class="mt-5 h-24 w-full overflow-visible"><polyline :points="points" fill="none" stroke="currentColor" stroke-width="2" vector-effect="non-scaling-stroke" class="text-brand-600"/></svg><p v-else class="mt-6 rounded-xl bg-slate-50 p-4 text-sm text-slate-500">هنوز داده کافی برای نمایش نمودار وجود ندارد.</p></div></section><section class="rounded-3xl border bg-white p-6 md:p-10"><h2 class="text-xl font-black">پرسش درباره محصول</h2><form class="mt-5" @submit.prevent="ask"><textarea v-model="question" required minlength="5" rows="3" class="w-full rounded-xl border p-3" placeholder="سؤال خود را بنویسید…"/><p v-if="message" class="mt-2 text-sm text-emerald-700">{{message}}</p><button class="mt-3 rounded-xl bg-brand-700 px-5 py-2.5 text-sm font-bold text-white">ارسال پرسش</button></form><div class="mt-6 space-y-3"><article v-for="item in questions?.data" :key="item.id" class="rounded-2xl bg-slate-50 p-5"><p class="font-bold">سؤال: {{item.question}}</p><p v-if="item.answer" class="mt-3 border-r-2 border-brand-600 pr-4 text-sm leading-7 text-slate-600">پاسخ: {{item.answer}}</p></article></div></section><section v-if="related.length"><div class="mb-5 flex justify-between"><h2 class="text-xl font-black">محصولات مشابه</h2><NuxtLink to="/products" class="text-sm font-bold text-brand-700">مشاهده همه</NuxtLink></div><div class="grid grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-5"><ProductCard v-for="item in related.slice(0,5)" :key="item.id" :product="item"/></div></section></div></template>
